// Serve starts accepting database connections from the provided listener.
func (s *ProxyServer) Serve(listener net.Listener) error {
	s.log.Debug("Started database proxy.")
	defer s.log.Debug("Database proxy exited.")
	for {
		// Accept the connection from the database client, such as psql.
		// The connection is expected to come through via multiplexer.
		clientConn, err := listener.Accept()
		if err != nil {
			if strings.Contains(err.Error(), constants.UseOfClosedNetworkConnection) || trace.IsConnectionProblem(err) {
				return nil
			}
			return trace.Wrap(err)
		}
		// The multiplexed connection contains information about detected
		// protocol so dispatch to the appropriate proxy.
		proxy, err := s.dispatch(clientConn)
		if err != nil {
			s.log.WithError(err).Error("Failed to dispatch client connection.")
			continue
		}
		// Let the appropriate proxy handle the connection and go back
		// to listening.
		go func() {
			defer clientConn.Close()
			err := proxy.HandleConnection(s.closeCtx, clientConn)
			if err != nil {
				s.log.WithError(err).Warn("Failed to handle client connection.")
			}

	// If server ID matches a node that has self registered itself over the tunnel,
	// return a tunnel connection to that node. Otherwise net.Dial to the target host.
	conn, tunnelErr := s.dialTunnel(dreq)
	if tunnelErr == nil {
		return conn, true, nil
	}

	if !trace.IsNotFound(tunnelErr) {
		return nil, false, trace.Wrap(tunnelErr)
	}

	s.log.WithError(tunnelErr).WithField("address", dreq.Address).Debug("Error occurred while dialing through a tunnel.")

	// Connections to application and database servers should never occur
	// over a direct dial, return right away.
	switch params.ConnType {
	case types.AppTunnel:
		return nil, false, trace.ConnectionProblem(err, "failed to connect to application server")
	case types.DatabaseTunnel:
		return nil, false, trace.ConnectionProblem(err, "failed to connect to database server")
	}

	offlineMsg := "the node is offline or has disconnected, if the issue " +
		"persists, restart the node or re-register it in the cluster"

	// This node can only be reached over a tunnel, don't attempt to dial
	// remotely.
	if params.To.String() == "" {
		return nil, false, trace.ConnectionProblem(tunnelErr, offlineMsg)
	}

	// If no tunnel connection was found, dial to the target host.
	dialer := proxy.DialerFromEnvironment(params.To.String())
	conn, directErr := dialer.DialTimeout(params.To.Network(), params.To.String(), apidefaults.DefaultDialTimeout)
	if directErr != nil {
		s.log.WithError(directErr).WithField("address", params.To.String()).Debug("Error occurred while dialing directly.")
		aggregateErr := trace.NewAggregate(tunnelErr, directErr)
		return nil, false, trace.ConnectionProblem(aggregateErr, offlineMsg)
	}


func (s *remoteSite) connThroughTunnel(req *sshutils.DialReq) (*sshutils.ChConn, error) {

	s.Debugf("Requesting connection to %v [%v] in remote cluster.",
		req.Address, req.ServerID)

	// Loop through existing remote connections and try and establish a
	// connection over the "reverse tunnel".
